resource "aws_ssm_parameter" "secret1" {
  name  = "/production/database/username"
  type  = "String"
  value = "admin"
}

resource "aws_ssm_parameter" "secret2" {
  name  = "/production/database/password"
  type  = "SecureString"
  value = "USMNT2023"
}


resource "aws_ssm_parameter" "secret3" {
  name  = "/staging/database/user"
  type  = "String"
  value = "admin"
}


resource "aws_ssm_parameter" "secret4" {
  name  = "/staging/database/password"
  type  = "String"
  value = "USMNT2023"
}

resource "aws_ssm_parameter" "flag" {
    name  = "/cloudfoxable/flag/its-a-secret"
    type  = "SecureString"
    value = "FLAG{ItsASecret::IsASecretASecretIfTooManyPeopleHaveAccessToIt?}"
}

// create an iam policy that only allows access to this flag
resource "aws_iam_policy" "its-a-secret-policy" {
  name        = "its-a-secret-policy"
  path        = "/"
  description = "policy that only allows access to the its-a-secret flag"

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "ssm:GetParameter"
        ],
        "Resource" : [
          aws_ssm_parameter.flag.arn
        ]
      }
    ]
  })
}

// attach this policy to the CTF starting user
resource "aws_iam_user_policy_attachment" "its-a-secret-policy-attachment" {
  user       = var.ctf_starting_user_name
  policy_arn = aws_iam_policy.its-a-secret-policy.arn
}

variable "aws_local_profile" {
  description = "What local profile should terraform use to interact with your AWS account(s)"
  type        = string
  default     = "default"
}

variable "aws_local_creds_file" {
  description = "Location of your local credentials file"
  type        = string
  default     = "~/.aws/credentials"
}

variable "aws_assume_role_arn" {
  description = "This is the arn of an already existing principal that can assume into any roles that are created"
  type        = string
  default     = ""
}

variable "account_id" {
  description = "This is the ID of the caller account"
  type        = string
  default     = ""
}


variable "shared_high_priv_servicerole" {
  description = "This is the arn of high priv service role that is attached to lambda's ec2's, etc. to facilitate privesc"
  type        = string
  default     = ""
}

variable "AWS_REGION" {
  type    = string
  default = "us-west-2"
}

# Resources
resource "random_password" "database-secret" {
  length           = 31
  special          = true
  min_special      = 5
  override_special = "!#$%^&*()-_=+[]{}<>:?"
  keepers = {
    pass_version = 1
  }
}

resource "random_password" "app-secret" {
  length           = 31
  special          = true
  min_special      = 5
  override_special = "!#$%^&*()-_=+[]{}<>:?"
  keepers = {
    pass_version = 1
  }
}

resource "random_string" "resource-suffix" {
  length           = 5 
  upper = false 
  special = false
}

variable "user_ip" {
  description = "The current user's IP address"
  type        = string
  default     = ""
}

variable "ctf_starting_user_arn" {
  description = "The arn of the user that is created at the start of the CTF"
  type        = string
  default     = ""
}

variable "ctf_starting_user_name" {
  description = "The name of the user that is created at the start of the CTF"
  type        = string
  default     = ""
}
